export function localeOf(p){return {...base,...languages[p.language],dir:p.direction==='rtl'?'rtl':p.direction==='ltr'?'ltr':languages[p.language]?.dir||'ltr',code:languages[p.language]?.code||p.languageCode||'en'};}
export function wordBand(n){return n<1000?'Flash fiction':n<7500?'Short story':n<17500?'Novelette':n<40000?'Novella':n<110000?'Novel / full-length nonfiction':'Epic / long-form book';}
export function creativityLabel(n){return n<30?'Grounded':n<70?'Balanced':'Daring';}
export function voiceInstructions(p){return `${p.style||'Restrained literary'}. Influence: ${p.authorStyle||'Original voice'}. ${authorVoices[p.authorStyle]||authorVoices.Custom} ${p.customAuthor||''}. Narrative point of view: ${p.pov||'Close third person'}. Tense: ${p.tense||'Past'}. Creativity ${p.creativity??50}/100 (${creativityLabel(p.creativity??50)}): change imaginative range, never established facts without permission. Style notes: ${p.styleNotes||''}. Write original prose; do not quote or reproduce an author's existing passages.`;}
export function imprintOf(p){return p.imprintName||p.imprint||'BookWiz Editions';}
export const proseKey=p=>JSON.stringify([p.language,p.genre,p.style,p.authorStyle,p.customAuthor,p.creativity,p.pov,p.tense,p.styleNotes,p.premise,p.world,JSON.stringify(p.characters||[]),(p.references||[]).map(r=>r.text).join('\n').slice(0,12000)]);
export function sampleFor(p){if(p.prosePreview?.key===proseKey(p))return p.prosePreview.text;const l=localeOf(p);if(p.language==='English'){if(p.genre==='Poetry')return 'The room kept its small square of light.\nA chair, an unopened letter,\nthe afternoon still waiting\nto be called by its name.';if(p.genre==='Mystery')return 'The envelope contained a key and a photograph of a room Mara had never entered. On the back, someone had written tomorrow’s date.';if(p.genre==='Fantasy')return 'At dawn the gardener found a name growing beneath the bark. She had planted the tree herself, twenty years before the person was born.';if(p.style==='Clear & direct')return 'Mara opened the letter at six. Her brother was alive. She read the sentence twice, folded the paper, and walked to the station.';if(p.authorStyle==='Jane Austen'||p.style==='Classic wit')return 'Mrs Vale regarded unexpected visitors as an inconvenience, unless they brought news of someone else’s troubles, in which case receiving them became a duty.';if(p.style==='Lyrical')return 'By morning the river had carried the rain into the sea, and the town woke silver, its windows holding small, uncertain pieces of sky.';}return l.sample;}
export function bookCSS(p){const [w,h]=trimOf(p),d=designOf(p),l=localeOf(p);const family=l.code==='ar'||l.code==='ur'?"'BookArabic',serif":l.code==='hi'?"'BookDevanagari',serif":l.code==='bn'?"'BookBengali',serif":d.font;return `@font-face{font-family:BookArabic;src:url('${new URL('assets/book-arabic.ttf',import.meta.url).href}')}@font-face{font-family:BookDevanagari;src:url('${new URL('assets/book-devanagari.ttf',import.meta.url).href}')}@font-face{font-family:BookBengali;src:url('${new URL('assets/book-bengali.ttf',import.meta.url).href}')}@page{size:${w}in ${h}in;margin:${d.margin}in;@bottom-center{content:counter(page);font:9pt ${family};color:#555}}@page:first{@bottom-center{content:none}}*{box-sizing:border-box}html{direction:${l.dir};background:#fff}body{font:${d.size}pt/${l.code==='ur'?Math.max(d.leading,1.9):d.leading} ${family};color:#20231f;margin:0}a{color:inherit;text-decoration:none}h1,h2,h3{font-family:${family};font-weight:400;line-height:1.25;text-align:${d.align};break-after:avoid;overflow-wrap:anywhere}h1{font-size:30pt}h2{font-size:25pt;margin:1.4em 0 1.7em}h3{font-size:16pt}p{margin:0 0 .6em;text-indent:1.25em;orphans:3;widows:3;white-space:pre-wrap}p:first-of-type{text-indent:0}.book-page{break-before:page;position:relative;min-height:${Math.max(2,h-d.margin*2-.1)}in}.front-page p{text-indent:0}.title-leaf{display:flex;min-height:${h-d.margin*2-.1}in;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding-bottom:.35in}.title-leaf h1{text-align:center;margin:0 0 .4in;max-width:100%}.title-leaf .book-subtitle{font-size:13pt;line-height:1.7;margin-bottom:.5in}.title-leaf .book-author{font-size:13pt}.book-imprint{font-size:10pt;letter-spacing:.1em;margin-top:auto;padding-top:.4in}.half-title{display:flex;align-items:center;justify-content:center;min-height:${h-d.margin*2-.1}in}.half-title h1{font-size:24pt;text-align:center}.copyright-leaf{display:flex;flex-direction:column;justify-content:flex-end;min-height:${h-d.margin*2-.1}in;font-size:9pt;line-height:1.7}.copyright-leaf p{margin-bottom:1em}.copyright-leaf a{overflow-wrap:anywhere}.dedication-leaf{text-align:center;padding-top:2in;font-style:italic}.chapter-label{text-align:${d.align};font-size:9pt;letter-spacing:.12em;text-transform:uppercase;color:${d.accent};margin:.5in 0 .25in;text-indent:0}.chapter-page h2{margin:0 0 .65in}.chapter-rule{width:.45in;height:1px;background:${d.accent};margin:${d.align==='center'?'0 auto .5in':'0 0 .5in'}}.contents-list{list-style:none;padding:0}.contents-list li{padding:.12in 0;border-bottom:1px solid #e5e5df;line-height:1.5}.contents-list span{display:inline-block;min-width:.3in;color:${d.accent}}blockquote{font-style:italic;margin:1.5em 1em}.book-colophon{font-size:8pt;text-align:center;margin-top:1in}.proof{background:#e9ebe4;padding:24px}.proof .book-page{width:${w}in;min-height:${h}in;padding:${d.margin}in;margin:0 auto 24px;background:white;box-shadow:0 5px 18px #27392718}.proof .title-leaf,.proof .half-title,.proof .copyright-leaf{min-height:${h-d.margin*2}in}.single-proof{margin:0;background:#fff}.single-proof .book-page{width:${w}in;min-height:${h}in;padding:${d.margin}in}.single-proof .chapter-page{padding-top:${d.margin}in}@media print{.single-proof .book-page{width:auto;padding:0;min-height:${h-d.margin*2-.1}in}.proof{padding:0;background:white}.proof .book-page{width:auto;padding:0;margin:0;min-height:${h-d.margin*2-.1}in;box-shadow:none}.book-page:first-child{break-before:auto}}`;}
export function frontMatterPages(p){const l=localeOf(p),f=p.frontMatter||{},pages=[];if(f.halfTitle!==false)pages.push({id:'half-title',label:l.half,html:`<section class="book-page front-page"><div class="half-title"><h1>${esc(p.title)}</h1></div></section>`});pages.push({id:'title',label:l.title,html:`<section class="book-page front-page"><div class="title-leaf"><h1>${esc(p.title)}</h1>${p.subtitle?`<p class="book-subtitle">${esc(p.subtitle)}</p>`:''}<p class="book-author">${esc(p.author)}</p><p class="book-imprint">${esc(imprintOf(p))}</p></div></section>`});pages.push({id:'publication',label:l.publication,html:`<section class="book-page front-page"><div class="copyright-leaf"><p>© ${Number(f.year)||new Date().getFullYear()} ${esc(p.author)}<br/>${esc(l.rights)}</p><p>${esc(imprintOf(p))}<br/>${esc(f.edition||l.edition)}</p><p>${esc(l.project)}<br/><a href="${PROJECT_URL}">github.com/muneebwanee/BookWizOfficial</a></p>${f.disclosure?`<p>${esc(f.disclosure)}</p>`:''}</div></section>`});if(f.dedication?.trim())pages.push({id:'dedication',label:l.dedication,html:`<section class="book-page front-page"><div class="dedication-leaf">${paragraphs(f.dedication)}</div></section>`});if(f.contents!==false)pages.push({id:'contents',label:l.contents,html:`<section class="book-page front-page"><h2>${esc(l.contents)}</h2><ol class="contents-list">${p.chapters.map((c,i)=>`<li><span>${i+1}</span> ${esc(c.title)}</li>`).join('')}</ol></section>`});if(f.includePreface!==false&&(p.preface||'').trim())pages.push({id:'preface',label:l.preface,html:`<section class="book-page front-page"><h2>${esc(l.preface)}</h2>${paragraphs(p.preface)}</section>`});return pages;}
export function chapterPage(p,c,index){const l=localeOf(p);return `<section class="book-page chapter-page"><p class="chapter-label">${esc(l.chapter)} ${index+1}</p><h2>${esc(c.title)}</h2><div class="chapter-rule"></div>${sanitizeHTML(c.text)}</section>`;}
export function printBookHTML(p,{proof=true,page=null}={}){const l=localeOf(p);let pages=[...frontMatterPages(p),...p.chapters.map((c,i)=>({id:'chapter-'+i,label:l.chapter+' '+(i+1),html:chapterPage(p,c,i)}))];if(page!==null)pages=pages.filter(x=>x.id===page);return `<!doctype html><html lang="${esc(l.code)}" dir="${l.dir}"><head><meta charset="utf-8"><title>${esc(p.title)}</title><style>${bookCSS(p)}</style></head><body class="${page!==null?'single-proof':proof?'proof':''}">${pages.map(x=>x.html).join('')}</body></html>`;}
const coverSegmenter=globalThis.Intl?.Segmenter?new Intl.Segmenter(undefined,{granularity:'grapheme'}):null;
const coverLetters=text=>coverSegmenter?Array.from(coverSegmenter.segment(text),x=>x.segment):Array.from(text);
function wrapText(text,limit){const lines=[];let line='';for(const word of String(text).split(/\s+/)){let letters=coverLetters(word);while(letters.length>limit){if(line){lines.push(line);line='';}lines.push(letters.slice(0,limit).join(''));letters=letters.slice(limit);}const part=letters.join('');if(coverLetters((line+' '+part).trim()).length>limit){lines.push(line);line=part;}else line+=(line?' ':'')+part;}if(line)lines.push(line);return lines;}

